-- Shatrunjay Hills — Web GIS Dashboard
-- PostGIS schema + database-driven RBAC + mock data.
-- Runs automatically on first container start via docker-entrypoint-initdb.d.

CREATE EXTENSION IF NOT EXISTS postgis;

-- ---------------------------------------------------------------------------
-- Schema
-- ---------------------------------------------------------------------------

CREATE TABLE roles (
    id   SERIAL PRIMARY KEY,
    name TEXT NOT NULL UNIQUE
);

CREATE TABLE users (
    id            SERIAL PRIMARY KEY,
    username      TEXT NOT NULL UNIQUE,
    password_hash TEXT NOT NULL,
    role_id       INTEGER NOT NULL REFERENCES roles (id) ON DELETE RESTRICT
);

-- Mixed geometry types (Polygon, LineString) live in one column, so the
-- column type stays generic; each layer's actual type is whatever was
-- inserted (validated with ST_GeometryType downstream if ever needed).
CREATE TABLE layers (
    id       SERIAL PRIMARY KEY,
    name     TEXT NOT NULL UNIQUE,
    geometry GEOMETRY(Geometry, 4326) NOT NULL
);

CREATE INDEX layers_geometry_idx ON layers USING GIST (geometry);

CREATE TABLE role_layer_permissions (
    role_id  INTEGER NOT NULL REFERENCES roles (id) ON DELETE CASCADE,
    layer_id INTEGER NOT NULL REFERENCES layers (id) ON DELETE CASCADE,
    PRIMARY KEY (role_id, layer_id)
);

-- The sidebar's tree. The client's layer structure is two and three levels
-- deep (Forest Layers > Forest Cover > its years), which the flat `section`
-- text column this replaces could not express: a group's parent is another
-- group, and every static overlay hangs off exactly one group.
--
-- Re-ordering the sidebar, renaming a heading or adding a whole branch of the
-- tree is a change to these rows, never to Go or TypeScript (CLAUDE.md's core
-- invariant). `key` is a stable slug the frontend uses for presentation
-- lookups (icon, accent colour) and its own state; `label` is what the
-- sidebar shows, so relabelling for the client invalidates nothing.
--
-- One rule the seed below relies on: a group that holds rasters holds exactly
-- one theme's rasters, because the frontend renders such a group as a single
-- layer with a year picker. Six unrelated drone rasters therefore get six
-- groups, not one.
CREATE TABLE layer_groups (
    id         SERIAL PRIMARY KEY,
    key        TEXT NOT NULL UNIQUE,
    label      TEXT NOT NULL,
    -- NULL for a top-level heading. A group is deleted with its subtree.
    parent_id  INTEGER REFERENCES layer_groups (id) ON DELETE CASCADE,
    sort_order INTEGER NOT NULL DEFAULT 0,
    -- A top-level group set true gets a navbar dropdown of its own, listing
    -- its layers directly, instead of being one entry in the Sections/Layers
    -- pair. Which groups do is this flag, never a key check in the frontend.
    own_picker BOOLEAN NOT NULL DEFAULT false,
    -- A raster group set true draws beneath every other raster (the
    -- Toposheet, a full-sheet reference map that would otherwise cover
    -- them). Vectors always draw above all rasters regardless.
    draw_below BOOLEAN NOT NULL DEFAULT false
);

CREATE INDEX layer_groups_parent_idx ON layer_groups (parent_id);

-- Resolves a group key to its id, so the seed rows below stay readable
-- instead of carrying a scalar subquery each. Kept (not dropped) so later
-- migrations that add layers can use it too.
CREATE FUNCTION grp(group_key TEXT) RETURNS INTEGER AS $$
    SELECT id FROM layer_groups WHERE key = group_key;
$$ LANGUAGE sql STABLE;

-- Vector reference geometry and raster imagery. Not RBAC-permissioned (every
-- visitor sees the same reference data), so no role_id here — just a key the
-- frontend switches on and a file_path the API resolves against DATA_ROOT to
-- serve the asset. Adding a new overlay (another vector layer, another raster
-- year) is a row insert here, not a frontend/API code change.
-- min_lon/min_lat/max_lon/max_lat (SW/NE corners, EPSG:4326) place a raster
-- overlay on the map — the source imagery has no embedded geo tags of its
-- own. NULL for vector rows, which carry their own geometry instead.
-- status lets a row announce a layer whose data hasn't been delivered yet
-- (e.g. Tree Species, alongside Tree Height in the same section) without a
-- frontend code change: 'pending' rows carry no kind/color/file_path and the
-- sidebar renders them as a disabled placeholder rather than a working
-- switch. Flip to 'available' and fill in kind/color/file_path once the data
-- arrives — no other row needs to change.
CREATE TABLE static_overlays (
    id         SERIAL PRIMARY KEY,
    key        TEXT NOT NULL UNIQUE,
    label      TEXT NOT NULL,
    -- The group this layer sits under in the sidebar. Replaces the old free
    -- text `section` column, which could only express one flat level.
    group_id   INTEGER NOT NULL REFERENCES layer_groups (id) ON DELETE RESTRICT,
    asset_type TEXT NOT NULL CHECK (asset_type IN ('vector', 'raster')),
    -- How a vector layer draws, and therefore what its legend swatch looks
    -- like. 'fill' is a solid-tinted area (Forest Boundary, Geology);
    -- 'outline' is a boundary drawn as an outline only, with no tint
    -- (Village/Taluka/District/Study Area) -- the brief asks for those two to
    -- be distinguishable in the legend. NULL for a raster row.
    kind       TEXT CHECK (kind IN ('line', 'fill', 'outline', 'point')),
    color      TEXT,
    file_path  TEXT NOT NULL,
    sort_order INTEGER NOT NULL DEFAULT 0,
    status     TEXT NOT NULL DEFAULT 'available' CHECK (status IN ('available', 'pending')),
    -- SW/NE corners. For a raster row this is where the image is placed on the
    -- map. For a vector row it is the extent of the geometry in file_path,
    -- which is what lets the frontend frame a layer it has switched on without
    -- first downloading and parsing the file to find out where it is. NULL on
    -- a 'pending' row, which has no file to describe.
    min_lon    DOUBLE PRECISION,
    min_lat    DOUBLE PRECISION,
    max_lon    DOUBLE PRECISION,
    max_lat    DOUBLE PRECISION,
    -- A vector layer normally draws in one flat `color`. A row whose features
    -- carry their own class (Forest Cover FSI's density classes, Forest
    -- Type's species types) instead sets color_field to the GeoJSON property
    -- holding that class, and categories to that class's value/label/color
    -- rows — the same shape lib/legend-config.ts already uses for a raster
    -- theme's classes, so the legend renders it the same way. NULL/NULL for
    -- every flat-colour row, which is still the common case.
    color_field TEXT,
    categories  JSONB,
    -- The GeoJSON properties a clicked feature's popup shows, in order. NULL
    -- shows every meaningful property (see apps/web/lib/feature-popup.ts).
    popup_fields TEXT[],
    -- Selected and switched on when the dashboard opens, before anything is
    -- picked. Which layers start on is this flag, not a key in the frontend.
    default_on BOOLEAN NOT NULL DEFAULT false
);

-- The client's official class statistics: area and share per class, per
-- overlay image (one year of Forest Cover, one Vegetation Change transition,
-- one FSI vector layer). Where a row exists here the Statistics panel shows
-- it instead of measuring the raster's pixels -- the delivered figures come
-- from the source GIS data, which the pixel count of a reprojected PNG can
-- only approximate, and the FSI vector layers have no pixels to count at all.
-- Overlays without rows keep the measured statistics.
--
-- class_value is the class's value in the theme's legend (the raster legends
-- in apps/web/lib/legend-config.ts, a vector layer's own `categories`): that
-- is how the frontend finds the class's colour and display name. `label` is
-- the delivered name, shown only if no legend class matches.
-- class_group heads a run of classes (Vegetation Change's Improvement /
-- Degradation / Stable); NULL elsewhere.
-- Rows are generated from the delivered spreadsheets by
-- tools/prepare-class-stats.py; a new delivery is a re-run of that script,
-- not a code change.
CREATE TABLE overlay_class_stats (
    overlay_id  INTEGER NOT NULL REFERENCES static_overlays (id) ON DELETE CASCADE,
    class_value TEXT NOT NULL,
    label       TEXT NOT NULL,
    class_group TEXT,
    area_ha     DOUBLE PRECISION NOT NULL,
    -- 0-100, as delivered.
    percentage  DOUBLE PRECISION NOT NULL,
    sort_order  INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (overlay_id, class_value)
);

-- ---------------------------------------------------------------------------
-- Seed: roles
-- ---------------------------------------------------------------------------

-- 'public' represents an anonymous (no-token) visitor — the API's Auth
-- middleware resolves a missing Authorization header to this role rather
-- than rejecting the request, so it needs the same row-based treatment as
-- any other role, not a special case in code.
INSERT INTO roles (name) VALUES
    ('regular_user'),
    ('admin'),
    ('support_team'),
    ('public');

