-- ---------------------------------------------------------------------------
-- Seed: permissions
-- public, regular_user -> shatrunjay_hill_boundary, roads, shetrunjay_hills_range, species_points
-- admin, support_team -> all five (adds metro_train)
-- ---------------------------------------------------------------------------

INSERT INTO role_layer_permissions (role_id, layer_id)
SELECT r.id, l.id
FROM roles r
CROSS JOIN layers l
WHERE
    (r.name IN ('public', 'regular_user') AND l.name IN ('shatrunjay_hill_boundary', 'roads', 'shetrunjay_hills_range', 'species_points'))
    OR (r.name IN ('admin', 'support_team'));

-- ---------------------------------------------------------------------------
-- Seed: layer groups (the sidebar tree)
--
-- Mirrors the client's "Layer Structure" list from the UI/UX brief. Every
-- heading they asked for exists here even where the data has not been
-- delivered, so the dashboard shows their structure from day one and each
-- delivery is a row update (status 'pending' -> 'available' plus a file_path)
-- rather than another schema or code change.
--
-- Three mappings were judgement calls, flagged rather than guessed silently:
--   * "Satellite Imagery" under Forest Layers is taken to be the FCC series,
--     the only satellite imagery stack delivered.
--   * "Forest Cover FSI" / "Forest Type FSI" read as naming the source of
--     those themes rather than separate layers, so they are not own groups.
-- ---------------------------------------------------------------------------

INSERT INTO layer_groups (key, label, parent_id, sort_order) VALUES
    ('forest-layers',               'Forest Layers',               NULL, 1),
    ('landuse',                     'Landuse',                     NULL, 2),
    ('drone-data',                  'Drone Data',                  NULL, 3),
    ('hydrogeology',                'Hydrogeology',                NULL, 4),
    ('drone-analysis',              'Drone Analysis',              NULL, 5),
    ('wildlife-movement',           'Wildlife Movement',           NULL, 7),
    ('administrative-boundaries',   'Administrative Boundaries',   NULL, 8);

-- Boundaries are reference context laid over whatever else is on, not a
-- subject of their own, so they get a dropdown of their own in the navbar.
UPDATE layer_groups SET own_picker = true WHERE key = 'administrative-boundaries';

-- Second level. Each of these holds one theme's rasters, so the frontend
-- renders it as a single layer with a year picker -- which is why the six
-- drone products get a group each rather than sharing one.
INSERT INTO layer_groups (key, label, parent_id, sort_order) VALUES
    ('green-cover',          'Green Cover (Yearwise)',  grp('forest-layers'), 1),
    ('forest-cover',         'Forest Cover (Yearwise)', grp('forest-layers'), 2),
    ('vegetation-change',    'Vegetation Change',       grp('forest-layers'), 4),
    ('forest-fragmentation', 'Forest Fragmentation',    grp('forest-layers'), 5),
    ('satellite-imagery',    'Satellite Imagery',       grp('forest-layers'), 6),

    ('historical-land-use',  'Historical Land Use (Satellite: 1978–2025)', grp('landuse'), 1),
    ('current-land-use',     'Current Land Use (Drone: 2026)',           grp('landuse'), 2),

    ('orthomosaic', 'Orthomosaic',                 grp('drone-data'), 1),
    ('dsm',         'DSM (Digital Surface Model)', grp('drone-data'), 2),
    ('dtm',         'DTM (Digital Terrain Model)', grp('drone-data'), 3),
    ('slope',       'Slope',                       grp('drone-data'), 4),
    ('aspect',      'Aspect',                      grp('drone-data'), 5),
    ('chm',         'CHM (Canopy Height Model)',   grp('drone-data'), 6),

    ('toposheet',   'Toposheet',                   grp('administrative-boundaries'), 12),

    ('flood-depth',                 'Flood Depth (m)',             grp('hydrogeology'), 1),
    ('existing-water-conservation', 'Existing Water Conservation', grp('hydrogeology'), 2),
    ('proposed-conservation-sites', 'Proposed Conservation Sites', grp('hydrogeology'), 3),

    ('habitat-suitability', 'Habitat Suitability', grp('wildlife-movement'), 1),
    ('wildlife-corridors',  'Wildlife Corridors',  grp('wildlife-movement'), 2);

UPDATE layer_groups SET draw_below = true WHERE key = 'toposheet';

-- Tree Density and Growing Stock are both rasters, so each gets its own group
-- under Drone Analysis: a group holding placed rasters becomes a single
-- layer, which would swallow Tree Height (and the still-pending rows) next
-- to it.
INSERT INTO layer_groups (key, label, parent_id, sort_order) VALUES
    ('tree-density',  'Tree Density',   grp('drone-analysis'), 1),
    ('growing-stock', 'Growing Stock',  grp('drone-analysis'), 2);

